                                        num_lay = gf_bs_read_int(bs, 3);
                                        for (j=0; j<=num_lay; j++) {
                                                u32 frameLengthType;
                                                Bool same_cfg = GF_FALSE;
                                                if (i || j) same_cfg = (Bool)gf_bs_read_int(bs, 1);

                                                if (!same_cfg) {
                                                        if (amux_version==1) gf_latm_get_value(bs);
                                                        gf_m4a_parse_config(bs, acfg, GF_FALSE);
                                                }
                                                frameLengthType = gf_bs_read_int(bs, 3);
